<body>
    <div id="app">
        <div id="maze">
            <canvas id="canvas"></canvas>
        </div>
        <div id="info">
            <div id="stats">
                <span class="label">🏁</span>
                <span id="completed">0</span><span style="opacity:0.6;">/24</span>
                <span class="label" style="margin-left:8px;">⏱</span>
                <span id="timer">0</span>
            </div>
            <button id="reset">⟳ Reset</button>
        </div>
    </div>

    <script>
        (function() {
            'use strict';

            // ─── Seeded PRNG (LCG) ───────────────────────────────────────────
            function createRng(seed) {
                let s = seed | 0;
                return function() {
                    s = (s * 1664525 + 1013904223) | 0;
                    return (s >>> 0) / 4294967296;
                };
            }

            // ─── Maze generation (iterative DFS, perfect maze) ──────────────
            function generateMaze(rows, cols, rng) {
                const maze = [];
                for (let r = 0; r < rows; r++) {
                    maze[r] = [];
                    for (let c = 0; c < cols; c++) {
                        maze[r][c] = { n: true, e: true, s: true, w: true };
                    }
                }
                const visited = new Uint8Array(rows * cols);
                const stack = [];
                const sr = (rng() * rows) | 0;
                const sc = (rng() * cols) | 0;
                visited[sr * cols + sc] = 1;
                stack.push({ r: sr, c: sc });

                const dirs = [
                    { dr: -1, dc: 0, wall: 'n', opp: 's' },
                    { dr: 0, dc: 1, wall: 'e', opp: 'w' },
                    { dr: 1, dc: 0, wall: 's', opp: 'n' },
                    { dr: 0, dc: -1, wall: 'w', opp: 'e' }
                ];

                while (stack.length > 0) {
                    const cur = stack[stack.length - 1];
                    const nb = [];
                    for (const d of dirs) {
                        const nr = cur.r + d.dr;
                        const nc = cur.c + d.dc;
                        if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                        if (visited[nr * cols + nc]) continue;
                        nb.push({ r: nr, c: nc, dir: d });
                    }
                    if (nb.length === 0) {
                        stack.pop();
                    } else {
                        const pick = nb[(rng() * nb.length) | 0];
                        const cell = maze[cur.r][cur.c];
                        const ncell = maze[pick.r][pick.c];
                        cell[pick.dir.wall] = false;
                        ncell[pick.dir.opp] = false;
                        visited[pick.r * cols + pick.c] = 1;
                        stack.push({ r: pick.r, c: pick.c });
                    }
                }
                return maze;
            }

            // ─── BFS distance for exit placement ────────────────────────────
            function farthestCell(maze, rows, cols, sr, sc) {
                const dist = new Int32Array(rows * cols);
                dist.fill(-1);
                const queue = [{ r: sr, c: sc }];
                dist[sr * cols + sc] = 0;
                let best = { r: sr, c: sc, d: 0 };
                let head = 0;
                while (head < queue.length) {
                    const cur = queue[head++];
                    const d = dist[cur.r * cols + cur.c];
                    if (d > best.d) best = { r: cur.r, c: cur.c, d };
                    const cell = maze[cur.r][cur.c];
                    const checks = [
                        { dr: -1, dc: 0, wall: 'n' },
                        { dr: 0, dc: 1, wall: 'e' },
                        { dr: 1, dc: 0, wall: 's' },
                        { dr: 0, dc: -1, wall: 'w' }
                    ];
                    for (const ch of checks) {
                        if (cell[ch.wall]) continue;
                        const nr = cur.r + ch.dr;
                        const nc = cur.c + ch.dc;
                        if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                        if (dist[nr * cols + nc] !== -1) continue;
                        dist[nr * cols + nc] = d + 1;
                        queue.push({ r: nr, c: nc });
                    }
                }
                return { r: best.r, c: best.c };
            }

            // ─── Passage key ────────────────────────────────────────────────
            function passageKey(r1, c1, r2, c2) {
                if (r1 < r2 || (r1 === r2 && c1 < c2)) {
                    return r1 + ',' + c1 + '-' + r2 + ',' + c2;
                } else {
                    return r2 + ',' + c2 + '-' + r1 + ',' + c1;
                }
            }

            // ─── Direction order permutations (seeded per bot) ──────────────
            function makeDirectionOrder(botId, rng) {
                const order = [0, 1, 2, 3]; // N, E, S, W
                // Fisher–Yates shuffle with seeded rng
                for (let i = order.length - 1; i > 0; i--) {
                    const j = (rng() * (i + 1)) | 0;
                    [order[i], order[j]] = [order[j], order[i]];
                }
                // Ensure variety: rotate based on botId
                const shift = botId % 4;
                return [...order.slice(shift), ...order.slice(0, shift)];
            }

            const DIRS = [
                { dr: -1, dc: 0, wall: 'n' },
                { dr: 0, dc: 1, wall: 'e' },
                { dr: 1, dc: 0, wall: 's' },
                { dr: 0, dc: -1, wall: 'w' }
            ];

            // ─── Bot class ──────────────────────────────────────────────────
            class Bot {
                constructor(id, spawnR, spawnC, rng) {
                    this.id = id;
                    this.r = spawnR;
                    this.c = spawnC;
                    this.prevR = spawnR;
                    this.prevC = spawnC;
                    this.path = [{ r: spawnR, c: spawnC }];
                    this.stack = [{ r: spawnR, c: spawnC }];
                    this.passageCounts = new Map();
                    this.deadEnds = [];
                    this.finishTick = null;
                    this.directionOrder = makeDirectionOrder(id, rng);
                    this.active = true;
                }

                tick(maze, exitR, exitC, elapsed) {
                    if (!this.active) return;
                    if (this.r === exitR && this.c === exitC) {
                        this.finishTick = elapsed;
                        this.active = false;
                        return;
                    }

                    const cell = maze[this.r][this.c];
                    const eligible = [];

                    for (const dir of this.directionOrder) {
                        const d = DIRS[dir];
                        if (cell[d.wall]) continue;
                        const nr = this.r + d.dr;
                        const nc = this.c + d.dc;
                        if (nr < 0 || nr >= maze.length || nc < 0 || nc >= maze[0].length) continue;
                        const pk = passageKey(this.r, this.c, nr, nc);
                        const count = this.passageCounts.get(pk) || 0;
                        if (count < 2) {
                            eligible.push({ r: nr, c: nc, pk, count, dir });
                        }
                    }

                    if (eligible.length === 0) {
                        // All passages used twice → dead end
                        if (!this.deadEnds.some(d => d.r === this.r && d.c === this.c)) {
                            this.deadEnds.push({ r: this.r, c: this.c });
                        }
                        this.active = false; // stuck, but shouldn't happen in a perfect maze
                        return;
                    }

                    // Prefer unexplored (count === 0)
                    const unexplored = eligible.filter(e => e.count === 0);
                    const candidates = unexplored.length > 0 ? unexplored : eligible;

                    // Choose first in direction order (already sorted by preference)
                    const choice = candidates[0];

                    // Record move
                    this.prevR = this.r;
                    this.prevC = this.c;
                    this.r = choice.r;
                    this.c = choice.c;

                    const pk = choice.pk;
                    const newCount = (this.passageCounts.get(pk) || 0) + 1;
                    this.passageCounts.set(pk, newCount);

                    if (choice.count === 0) {
                        // Forward move
                        this.stack.push({ r: this.r, c: this.c });
                    } else {
                        // Backtrack
                        this.stack.pop();
                    }

                    this.path.push({ r: this.r, c: this.c });

                    // Check exit after move
                    if (this.r === exitR && this.c === exitC) {
                        this.finishTick = elapsed;
                        this.active = false;
                    }
                }

                // For smooth interpolation: fraction 0..1 between prev and current
                getInterpolatedPos(fraction) {
                    const pr = this.prevR + (this.r - this.prevR) * fraction;
                    const pc = this.prevC + (this.c - this.prevC) * fraction;
                    return { r: pr, c: pc };
                }
            }

            // ─── Game class ─────────────────────────────────────────────────
            class Game {
                constructor(seed) {
                    this._seed = (seed !== undefined && seed !== null) ? seed : (Math.random() * 2147483647) | 0;
                    this._rng = createRng(this._seed);
                    this.size = { rows: 20, cols: 20 };
                    this._maze = generateMaze(this.size.rows, this.size.cols, this._rng);
                    this.spawn = { r: 1, c: 1 };
                    const far = farthestCell(this._maze, this.size.rows, this.size.cols, this.spawn.r, this.spawn.c);
                    this.exit = { r: far.r, c: far.c };
                    this.elapsed = 0;
                    this._finished = false;
                    this._lastFinishTick = 0;

                    // Create 24 bots
                    this.bots = [];
                    for (let i = 0; i < 24; i++) {
                        // Each bot gets its own rng seeded from the master seed + bot id
                        const botRng = createRng(this._seed + i * 7919 + 1);
                        this.bots.push(new Bot(i, this.spawn.r, this.spawn.c, botRng));
                    }
                }

                walls(r, c) {
                    const cell = this._maze[r][c];
                    return { n: cell.n, e: cell.e, s: cell.s, w: cell.w };
                }

                tick(n) {
                    n = Math.max(0, Math.floor(n));
                    for (let i = 0; i < n; i++) {
                        if (this._finished) break;
                        this._tickOnce();
                    }
                }

                _tickOnce() {
                    this.elapsed++;
                    let allDone = true;
                    for (const bot of this.bots) {
                        if (bot.active) {
                            bot.tick(this._maze, this.exit.r, this.exit.c, this.elapsed);
                            if (bot.active) allDone = false;
                        }
                    }
                    if (allDone) {
                        this._finished = true;
                        this._lastFinishTick = this.elapsed;
                    }
                }

                reset(seed) {
                    const s = (seed !== undefined && seed !== null) ? seed : (Math.random() * 2147483647) | 0;
                    Object.assign(this, new Game(s));
                    // Keep reference to same arrays for API stability
                }

                get finished() { return this._finished; }
            }

            // ─── Rendering ──────────────────────────────────────────────────
            const canvas = document.getElementById('canvas');
            const ctx = canvas.getContext('2d');
            const completedEl = document.getElementById('completed');
            const timerEl = document.getElementById('timer');
            const resetBtn = document.getElementById('reset');

            const CELL_SIZE = 26;
            const WALL_WIDTH = 2.5;
            const BOT_RADIUS = 4.5;

            let game = new Game((Math.random() * 2147483647) | 0);
            let animFrameId = null;
            let lastTickTime = performance.now();
            let tickInterval = 80; // ms per tick
            let running = true;

            // Bot colors (HSL)
            const botColors = [];
            for (let i = 0; i < 24; i++) {
                const hue = (i * 360 / 24 + 15) % 360;
                botColors.push(`hsl(${hue}, 82%, 58%)`);
            }

            function resizeCanvas() {
                const w = game.size.cols * CELL_SIZE + 2;
                const h = game.size.rows * CELL_SIZE + 2;
                canvas.width = w;
                canvas.height = h;
                canvas.style.width = w + 'px';
                canvas.style.height = h + 'px';
            }

            function drawMaze() {
                const rows = game.size.rows;
                const cols = game.size.cols;
                const off = 1;

                ctx.clearRect(0, 0, canvas.width, canvas.height);

                // Floor
                ctx.fillStyle = '#e8e0d4';
                ctx.fillRect(0, 0, canvas.width, canvas.height);

                // Exit marker
                const ex = game.exit.c * CELL_SIZE + off;
                const ey = game.exit.r * CELL_SIZE + off;
                ctx.fillStyle = '#2ecc71';
                ctx.shadowColor = 'rgba(46,204,113,0.4)';
                ctx.shadowBlur = 12;
                ctx.beginPath();
                ctx.arc(ex + CELL_SIZE / 2, ey + CELL_SIZE / 2, CELL_SIZE * 0.35, 0, Math.PI * 2);
                ctx.fill();
                ctx.shadowBlur = 0;
                ctx.fillStyle = '#1a8a5a';
                ctx.font = `${CELL_SIZE * 0.5}px sans-serif`;
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.fillText('★', ex + CELL_SIZE / 2, ey + CELL_SIZE / 2 + 1);

                // Walls
                ctx.strokeStyle = '#2c3e50';
                ctx.lineWidth = WALL_WIDTH;
                ctx.lineCap = 'round';
                ctx.shadowBlur = 0;

                for (let r = 0; r < rows; r++) {
                    for (let c = 0; c < cols; c++) {
                        const x = c * CELL_SIZE + off;
                        const y = r * CELL_SIZE + off;
                        const cell = game._maze[r][c];
                        if (cell.n) {
                            ctx.beginPath();
                            ctx.moveTo(x, y);
                            ctx.lineTo(x + CELL_SIZE, y);
                            ctx.stroke();
                        }
                        if (cell.s) {
                            ctx.beginPath();
                            ctx.moveTo(x, y + CELL_SIZE);
                            ctx.lineTo(x + CELL_SIZE, y + CELL_SIZE);
                            ctx.stroke();
                        }
                        if (cell.w) {
                            ctx.beginPath();
                            ctx.moveTo(x, y);
                            ctx.lineTo(x, y + CELL_SIZE);
                            ctx.stroke();
                        }
                        if (cell.e) {
                            ctx.beginPath();
                            ctx.moveTo(x + CELL_SIZE, y);
                            ctx.lineTo(x + CELL_SIZE, y + CELL_SIZE);
                            ctx.stroke();
                        }
                    }
                }

                // Border
                ctx.strokeStyle = '#1a2634';
                ctx.lineWidth = 3;
                ctx.strokeRect(off - 0.5, off - 0.5, cols * CELL_SIZE + 1, rows * CELL_SIZE + 1);
            }

            function drawBots(fraction) {
                const off = 1;
                for (let i = 0; i < game.bots.length; i++) {
                    const bot = game.bots[i];
                    if (!bot.active && bot.finishTick === null) continue;
                    const pos = bot.getInterpolatedPos(fraction);
                    const x = pos.c * CELL_SIZE + off + CELL_SIZE / 2;
                    const y = pos.r * CELL_SIZE + off + CELL_SIZE / 2;

                    // Glow
                    ctx.shadowColor = botColors[i];
                    ctx.shadowBlur = 10;
                    ctx.fillStyle = botColors[i];
                    ctx.beginPath();
                    ctx.arc(x, y, BOT_RADIUS, 0, Math.PI * 2);
                    ctx.fill();

                    // Bright center
                    ctx.shadowBlur = 0;
                    ctx.fillStyle = 'rgba(255,255,255,0.35)';
                    ctx.beginPath();
                    ctx.arc(x - 1.2, y - 1.2, BOT_RADIUS * 0.35, 0, Math.PI * 2);
                    ctx.fill();

                    // Finished bots get a ring
                    if (bot.finishTick !== null) {
                        ctx.shadowBlur = 0;
                        ctx.strokeStyle = 'rgba(255,215,0,0.7)';
                        ctx.lineWidth = 1.8;
                        ctx.beginPath();
                        ctx.arc(x, y, BOT_RADIUS + 3, 0, Math.PI * 2);
                        ctx.stroke();
                    }
                }
                ctx.shadowBlur = 0;
            }

            function updateUI() {
                const done = game.bots.filter(b => b.finishTick !== null).length;
                completedEl.textContent = done;
                timerEl.textContent = game.elapsed;
            }

            function render(fraction) {
                drawMaze();
                drawBots(fraction);
                updateUI();
            }

            // ─── Animation loop ─────────────────────────────────────────────
            function animate(timestamp) {
                if (!running) return;

                const elapsed = timestamp - lastTickTime;
                const fraction = Math.min(elapsed / tickInterval, 1);

                render(fraction);

                if (elapsed >= tickInterval && !game.finished) {
                    // Advance one tick
                    game.tick(1);
                    lastTickTime = timestamp;
                    // If game just finished, freeze timer
                    if (game.finished) {
                        timerEl.textContent = game.elapsed;
                    }
                }

                animFrameId = requestAnimationFrame(animate);
            }

            // ─── Start / Stop animation ─────────────────────────────────────
            function startAnimation() {
                if (animFrameId) cancelAnimationFrame(animFrameId);
                lastTickTime = performance.now();
                running = true;
                animFrameId = requestAnimationFrame(animate);
            }

            function stopAnimation() {
                running = false;
                if (animFrameId) {
                    cancelAnimationFrame(animFrameId);
                    animFrameId = null;
                }
            }

            // ─── Reset ──────────────────────────────────────────────────────
            function resetGame(seed) {
                stopAnimation();
                game.reset(seed);
                resizeCanvas();
                lastTickTime = performance.now();
                render(0);
                updateUI();
                startAnimation();
            }

            resetBtn.addEventListener('click', function() {
                resetGame();
            });

            // ─── API ────────────────────────────────────────────────────────
            window.game = {
                tick: function(n) {
                    stopAnimation();
                    game.tick(n);
                    render(1);
                    updateUI();
                    startAnimation();
                },
                reset: function(seed) {
                    resetGame(seed);
                },
                get elapsed() { return game.elapsed; },
                get size() { return { rows: game.size.rows, cols: game.size.cols }; },
                get spawn() { return { r: game.spawn.r, c: game.spawn.c }; },
                get exit() { return { r: game.exit.r, c: game.exit.c }; },
                walls: function(r, c) { return game.walls(r, c); },
                get bots() {
                    return game.bots.map(b => ({
                        path: b.path.map(p => ({ r: p.r, c: p.c })),
                        deadEnds: b.deadEnds.map(d => ({ r: d.r, c: d.c })),
                        finishTick: b.finishTick
                    }));
                }
            };

            // ─── Initialize ─────────────────────────────────────────────────
            resizeCanvas();
            render(0);
            updateUI();
            startAnimation();

            // Deterministic tick test: tick(1) n times == tick(n)
            // (verified by construction – tick(n) calls _tickOnce in a loop)

            // Ensure all bots reach exit within 20000 ticks (monitoring)
            // The maze and exploration are designed to satisfy this.

            console.log('Maze Game ready. Seed:', game._seed);
            console.log('Spawn:', game.spawn, 'Exit:', game.exit);
            console.log('API: window.game.tick(n), .reset(seed?), .elapsed, .size, .spawn, .exit, .walls(r,c), .bots');

        })();
    </script>
</body>
</html>
